conditions.value_template:
{% set f, t = trigger.from_state, trigger.to_state %}
{% if f is none or f.state != 'on' or t.state != 'on' or t.context.parent_id is not none %}false
{% else %}
{% set dk = ((t.attributes.color_temp_kelvin or 0) - states('sensor.desk_lamp_target_colour') | int(0)) | abs %}
{% set db = ((t.attributes.brightness or 0) / 2.55 - states('sensor.desk_lamp_target_brightness') | int(0)) | abs %}
{{ dk > 250 or db > 12 }}
{% endif %}
